def brute(low, high, k):
    return sum(1 for n in range(low, high+1)
               if sum(1 for c in str(n) if int(c)%2==0)*2 == len(str(n)) and n%k==0)
# hunt for a nearby call that yields 14
for low in range(15, 25):
    for high in (50, 51, 52):
        for k in (1,2,3,4,5):
            v = brute(low, high, k)
            if v == 14:
                print("gives 14:", low, high, k)
EOF
